import std.io

pub type AppError = Failed(String)

record Box { value: Int64 }

fn churn() -> Int64 {
    var i: Int64 = 0
    var acc: Int64 = 0
    while i < 20000 {
        let xs = [i, i + 1, i + 2, i + 3]
        for x in xs {
            acc = acc + x
        }
        i = i + 1
    }
    return acc
}

fn boxes(n: Int64) -> Int64 {
    var i: Int64 = 0
    var s: Int64 = 0
    while i < n {
        let t = Box { value: i }
        s = s + t.value
        i = i + 1
    }
    return s
}

fn maybe(c: Bool) -> Int64 {
    if c {
        let xs = [1, 2, 3]
        return 1
    }
    return 0
}

pub fn main() effect io -> Result<(), AppError> {
    let a = Box { value: 42 }
    let b = Box { value: 7 }
    let k = maybe(false)
    let n = churn()
    let m = boxes(64)
    io.println("${a.value + b.value + k} ${n} ${m}")
    return Ok(())
}
